/* DEADLINE XP v2 — deterministic, local-only support investigation. */
const E=window.CASE.artifacts;
const initialIncident=()=>({schemaVersion:2,caseVersion:CASE.version,mode:'standard',read:[],pinned:[],notes:'',chronology:{},claims:{},isolated:null,quarantined:false,helperRunning:true,helperStartup:true,archive:false,source:null,sourceProof:false,mirrorRejected:false,deltas:[],reviewed:[],revision:0,test:null,ledger:[],triggered:{},hints:{},optional:[],ending:null,output:false,minutes:0,unsafe:0,bookingErrors:0,feedback:'',access:{reduced:false,large:false},started:Date.now()});
let incident=initialIncident(),folderNow='root',mailFolder='Inbox',mailSelected='E01',mailQuery='',browserPage='B03',viewerZoom=100,pendingAction=null,operationBusy=false,caseTab='overview',shotPlaying=false,clipPosition=0,clipTimer=null,cosmeticTimer=null,remotePaused=false;
const xpOpenApp=openApp;
const folders={root:'My Documents',reception:'Reception incident',screenshots:'Reception Screenshots',office:'Office Records',events:'Events',finance:'Finance',archive:'Recovery Archive',downloads:'Reception Downloads',outputs:'Recovery outputs'};
const appNames={P01:'Contain reception',P02:'Installation timeline',P03:'Installed helper',P04:'Recovery copies',P05:'Booking changes',P06:'Test and handover'};
const esc=v=>escapeHTML(String(v??''));
const clockTime=(m=555+incident.minutes)=>String(Math.floor(m/60)%24).padStart(2,'0')+':'+String(m%60).padStart(2,'0');
const artifactTitle=id=>E[id]?.title||({'R01':'Working change ledger','R02':'Local verification report','R03':'Handover note','R04':'Cash case report'}[id]||id);
const evidenceAvailable=id=>incident.read.includes(id)||incident.pinned.includes(id);
const readAny=(...ids)=>ids.some(evidenceAvailable);
const helperSafe=()=>!incident.helperRunning&&!incident.helperStartup;
const contained=()=>incident.isolated==='PC-04';
const stageReady=()=>contained()&&helperSafe()&&incident.quarantined;
const correctDeltas=()=>incident.source==='A03'&&incident.deltas.length===3&&incident.deltas[0].ref==='MH-231'&&incident.deltas[0].qty===2&&incident.deltas[0].source==='E07'&&incident.deltas[1].ref==='MH-209'&&incident.deltas[1].qty===-1&&incident.deltas[1].source==='E08'&&incident.deltas[2].qty===0;
const fullReady=()=>contained()&&helperSafe()&&incident.quarantined&&correctDeltas()&&incident.test?.revision===incident.revision&&incident.test.checks.every(c=>c.pass)&&incident.reviewed.includes('MH-231')&&incident.reviewed.includes('MH-209');
const partialReady=()=>contained()&&helperSafe()&&['A02','A03'].includes(incident.source);
function incidentKey(){return 'deadline:case-v2:'+profile}
function saveIncident(){try{localStorage.setItem(incidentKey(),JSON.stringify(incident));localStorage.setItem('deadline-user',profile)}catch{incident.feedback='Browser storage is unavailable. Keep this tab open; this session cannot be saved.'}tick()}
save=function(){saveIncident()};
tick=function(){$('#clock').textContent=clockTime();$('#clock').title='Incident clock: advances only when you apply an action. '+CASE.date};
integrity=function(){return Math.max(incident.mode==='relaxed'?1:0,Math.round(100*(7-incident.unsafe)/7))};
function windowShow(id,title,html,width=730){closeWin(id);let el=win(id,title,html,width);el.style.left=id==='game'?'17%':id==='mail'?'12%':id.startsWith('ev-')?'19%':'23%';el.style.top='7%';el.style.zIndex=++z;return el}
function pageButton(action,label){return `<button type="button" class="btn" onclick="${action}">${label}</button>`}
function info(message){incident.feedback=message;saveIncident();let w=windowShow('notice','Duty Support — Information',`<div class="setting"><p role="status">${esc(message)}</p><div class="wizard-footer">${pageButton("closeWin('notice')",'OK')}</div></div>`,460);return w}
function recordRead(id){if(E[id]&&!incident.read.includes(id)){incident.read.push(id);saveIncident();document.querySelectorAll('select[data-proof]').forEach(sel=>{if(![...sel.options].some(o=>o.value===id)){let o=document.createElement('option');o.value=id;o.textContent=id+' — '+artifactTitle(id);sel.append(o)}})}}
function pinEvidence(id){recordRead(id);if(!incident.pinned.includes(id))incident.pinned.push(id);saveIncident();document.querySelectorAll('select[data-proof]').forEach(sel=>{if(![...sel.options].some(o=>o.value===id)){let o=document.createElement('option');o.value=id;o.textContent=id+' — '+artifactTitle(id);sel.append(o)}});document.querySelectorAll(`[data-pin="${id}"]`).forEach(b=>b.textContent='✓ Saved finding');toast('Finding saved',artifactTitle(id)+' is available in Case Notes. Pinning is optional; inspected sources can also support an action.')}
function footer(id){return `<div class="evidence-footer"><span>${id} · ${esc(E[id]?.time||'Derived')} · Read-only incident copy</span><div>${pageButton(`compareSource('${id}')`,'Compare')}${pageButton(`sourceProperties('${id}')`,'Properties')}<button class="btn" data-pin="${id}" onclick="pinEvidence('${id}')">${incident.pinned.includes(id)?'✓ Saved finding':'Save finding'}</button></div></div>`}
function proofSelect(name,label,selected=''){return `<label class="form-row">${label}<select name="${name}" data-proof><option value="">Attach an inspected source…</option>${incident.read.filter(id=>E[id]).map(id=>`<option value="${id}" ${id===selected?'selected':''}>${id} — ${esc(artifactTitle(id))}</option>`).join('')}</select></label>`}
function chosen(form,...names){return names.map(n=>form.elements[n]?.value).filter(Boolean)}
function has(proofs,...ids){return ids.some(id=>proofs.includes(id))}
function triggerMail(id){if(incident.triggered[id])return;incident.triggered[id]={time:clockTime(),order:Object.keys(incident.triggered).length};saveIncident();toast('You have new mail',artifactTitle(id)+' — Shared Operations mailbox')}
function bodyHTML(e){let body=esc(e.body||'').replace(/\n/g,'<br>');if(e.id==='E05')body+=`<p><a href="#" onclick="event.preventDefault();openBrowser('B02')">http://meridian-visitor.net/desk</a></p>`;if(e.id==='E11')body+=`<p><a href="#" onclick="event.preventDefault();openBrowser('B06')">Open saved repair offer</a></p>`;if(e.id==='E02')body+=`<div class="mail-attachments">Attachments: ${['S01','S02','S03','S04','E05'].map(id=>`<button class="link" onclick="viewEvidence('${id}')">${esc(artifactTitle(id))}</button>`).join(' · ')}</div>`;return body}
function sourceProperties(id){const e=E[id];windowShow('properties','Properties — '+e.title,`<div class="setting"><h3>${esc(e.title)}</h3><table class="native-table"><tr><td>Source ID</td><td>${id}</td></tr><tr><td>Original time</td><td>${esc(e.stamp||e.time)}</td></tr><tr><td>Collected</td><td>17 November 2006, 09:12 / authorised Operations support</td></tr>${e.from?`<tr><td>Full sender</td><td>${esc(e.from)}</td></tr><tr><td>Recipients</td><td>${esc(e.to)}</td></tr>`:''}<tr><td>Status</td><td>Preserved read-only copy. No files on your device are accessed.</td></tr></table>${id==='E05'?'<p>Original link: http://meridian-visitor.net/desk<br>Received: 17 November 2006, 08:41</p>':''}<div class="wizard-footer">${pageButton("closeWin('properties')",'Close')}</div></div>`,600)}
function compareSource(id){windowShow('compare','Compare incident sources',`<div class="setting"><h3>Compare records</h3><form onsubmit="event.preventDefault();showComparison('${id}',this.elements.other.value)">${proofSelect('other','Compare '+id+' with')}<button class="btn">Open side by side</button></form></div>`,520)}
function showComparison(a,b){if(!b||!E[b])return;windowShow('compare','Compare — '+a+' / '+b,`<div class="compare-columns">${[a,b].map(id=>`<article><h3>${id} — ${esc(artifactTitle(id))}</h3><div class="source-transcript">${bodyHTML(E[id])}</div></article>`).join('')}</div>`,900)}
function viewEvidence(id){if(id.startsWith('R')){openReport(id);return}const e=E[id];if(!e)return;if(e.type==='mail'){mailSelected=id;openMail(e.folder);return}if(e.type==='browser'){openBrowser(id);return}if(e.folder==='archive'&&!incident.archive){openDocuments('archive');return}recordRead(id);let html=e.type==='shot'?`<div class="picture-toolbar">${pageButton('zoomPicture(-10)','−')}<span id="zoomLabel">100%</span>${pageButton('zoomPicture(10)','+')}<button class="link" onclick="document.querySelector('#imageTranscript').hidden=!document.querySelector('#imageTranscript').hidden">Text transcript</button>${id==='S03'?pageButton('openCCTV()','Play saved clip'):''}</div><div class="picture-canvas"><div id="shotCanvas">${renderShot(id)}</div></div><div id="imageTranscript" class="source-transcript" hidden>${esc(e.body)}</div>`:`<div class="notepad">${esc(e.body)}</div>`;viewerZoom=100;windowShow('ev-'+id,e.title+(e.type==='shot'?' — Windows Picture and Fax Viewer':' — Notepad'),html+footer(id),e.type==='shot'?690:620)}
function zoomPicture(delta){viewerZoom=Math.max(65,Math.min(160,viewerZoom+delta));const el=$('#shotCanvas');if(el)el.style.zoom=viewerZoom+'%';if($('#zoomLabel'))$('#zoomLabel').textContent=viewerZoom+'%'}
function renderShot(id){let content='';let stamp=E[id].time;if(id==='S03')return roomScene(false)+`<p class="shot-caption">Corridor camera export · Display clock not corrected. Two indistinct figures; no identifiable keyboard action.</p>`;if(id==='S01')content=`<b>Visitor List Viewer setup completed</b><p>Installed component: Visitor List Helper</p><p>File: VisitorList_Update.exe<br>C:\\Program Files\\Visitor List\\vlhelper.exe</p><div style="text-align:right"><span class="capture-button">Finish</span></div>`;if(id==='S02')content='<b>Booking Desk</b><p>gala.book cannot be opened — file locked or unreadable.</p><p>Last successful read: 08:56</p><div style="text-align:right"><span class="capture-button">OK</span></div>';if(id==='S04')content=`<table class="native-table"><tr><th>Name</th><th>Path</th><th>Added</th></tr><tr><td>Booking Desk</td><td>C:\\Program Files\\Booking Desk</td><td>12 Sep</td></tr><tr><td>Printer Status</td><td>C:\\Printer</td><td>12 Sep</td></tr><tr><td>Office Backup</td><td>C:\\Office Backup</td><td>12 Sep</td></tr><tr><td>Visitor List Helper</td><td>C:\\Program Files\\Visitor List\\vlhelper.exe</td><td>08:58</td></tr></table>`;if(id==='S05')content='<h2>MERIDIAN HOUSE</h2><p>Welcome to the Lantern Gala</p><p>Welcome Loop / PC-07 Events<br>C:\\Program Files\\Welcome Loop\\welcome.exe</p><p>16 November 2006, 15:22</p>';return `<div class="desktop-capture"><div class="capture-asset">${id==='S05'?'PC-07 / Events':'PC-04 / Reception'} · ${esc(stamp)}</div><div class="capture-window" style="left:5%;top:16%;width:90%"><div class="capture-title">${id==='S01'?'Visitor List Viewer Setup':id==='S04'?'Startup Programs':id==='S05'?'Welcome Loop':'Booking Desk'} <b>×</b></div><div class="capture-body">${content}</div></div><div class="capture-taskbar"><img src="assets/start.png" alt="">${esc(stamp)}</div></div><p class="shot-caption">Fictional recreated screen capture · Source preserved at 09:12.</p>`}
function roomScene(playing){return `<div class="cctv-scene ${playing&&!incident.access.reduced?'playing':''}"><div class="cctv-overlay">NORTH CORRIDOR / <span id="clipClock">08:48:00</span></div><div class="room-back"><span>RECEPTION</span><div class="room-door"></div></div><div class="room-floor"></div><div class="room-wall"></div><div class="room-desk"></div><div class="room-monitor"></div><div class="room-person person-one"></div><div class="room-person person-two"></div><div class="cctv-grain"></div><div class="cctv-bottom">CAM 02 · ARCHIVED COPY · Camera display not corrected</div></div>`}
function openCCTV(){recordRead('S03');pauseClip();clipPosition=0;shotPlaying=false;windowShow('cctv','Corridor_0848.avi — Windows Media Player',`<div class="media-toolbar">File &nbsp; View &nbsp; Play &nbsp; Tools &nbsp; Help</div><div class="media-screen" id="mediaScene">${roomScene(false)}</div><div class="media-controls"><button class="btn" onclick="toggleClip()" id="clipButton">Play</button><label>Frame <input type="range" min="0" max="12" step="0.1" value="0" aria-label="Clip frame" oninput="scrubClip(this.value)"></label><span id="clipElapsed">00:00 / 00:12</span></div><div class="source-transcript">Saved camera clip: two indistinct figures in a corridor. The display begins at 08:48:00 and is not corrected. Identity and keyboard use cannot be established from the clip. Fictional visual reconstruction.</div>${footer('S03')}`,700)}
function pauseClip(){clearInterval(clipTimer);clipTimer=null;shotPlaying=false;const b=$('#clipButton');if(b)b.textContent='Play';document.querySelectorAll('.cctv-scene').forEach(el=>el.classList.remove('playing'))}
function toggleClip(){if(shotPlaying){pauseClip();return}if(clipPosition>=12)clipPosition=0;shotPlaying=true;$('#clipButton').textContent='Pause';clipTimer=setInterval(()=>{if(!windows.has('cctv')||paused||document.hidden){pauseClip();return}clipPosition=Math.min(12,clipPosition+.1);renderClipPosition();if(clipPosition>=12)pauseClip()},100)}
function renderClipPosition(){const sec=Math.floor(clipPosition),clock=$('#clipClock');if(clock)clock.textContent='08:48:'+String(sec).padStart(2,'0');const slider=document.querySelector('[aria-label="Clip frame"]');if(slider)slider.value=String(clipPosition);const progress=$('#clipElapsed');if(progress)progress.textContent='00:'+String(sec).padStart(2,'0')+' / 00:12';if(!incident.access.reduced){document.querySelector('#mediaScene .person-one')?.style.setProperty('left',(43+clipPosition)+'%');document.querySelector('#mediaScene .person-two')?.style.setProperty('left',(67-clipPosition/3)+'%')}}
function scrubClip(v){pauseClip();clipPosition=Number(v);renderClipPosition()}
function visibleArtifact(id){return !E[id].triggered||incident.triggered[id]}
function folderGrid(folder,query=''){const q=query.toLowerCase();if(folder==='root'&&!q)return Object.entries(folders).filter(([k])=>k!=='root').map(([id,name])=>`<button class="folder-item" ondblclick="openDocuments('${id}')" onkeydown="if(event.key==='Enter')openDocuments('${id}')"><img src="assets/folder.png" alt=""><span>${name}</span>${id==='archive'?'<small>Restricted access</small>':''}</button>`).join('');if(folder==='outputs'&&!q)return ['R04','R01','R02','R03'].map(id=>`<button class="folder-item" onclick="openReport('${id}')"><img src="assets/icon-35.ico" alt=""><span>${artifactTitle(id)}</span></button>`).join('');if(folder==='downloads'&&!q)return `<button class="folder-item" ondblclick="fileProperties('VisitorList_Update.exe')" onkeydown="if(event.key==='Enter')fileProperties('VisitorList_Update.exe')"><img src="assets/icon-3.ico" alt=""><span>VisitorList_Update.exe</span><small>Preserved installer</small></button><button class="folder-item" onclick="fileProperties('badge_layout.pdf')"><img src="assets/icon-1.ico" alt=""><span>badge_layout.pdf</span></button><button class="folder-item" onclick="fileProperties('welcome_card.jpg')"><img src="assets/icon-1.ico" alt=""><span>welcome_card.jpg</span></button>`;return Object.values(E).filter(e=>!['mail','browser'].includes(e.type)&&(q?(e.title+' '+e.body).toLowerCase().includes(q):e.folder===folder)&&(e.folder!=='archive'||incident.archive)).map(e=>`<button class="folder-item" ondblclick="viewEvidence('${e.id}')" onkeydown="if(event.key==='Enter')viewEvidence('${e.id}')"><img src="assets/${e.type==='shot'?'icon-1.ico':'icon-35.ico'}" alt=""><span>${esc(e.title)}</span><small>${e.id} · ${incident.pinned.includes(e.id)?'Finding saved':incident.read.includes(e.id)?'Read':'Read-only'}</small></button>`).join('')||'<p>No matching files in accessible incident copies.</p>'}
function openDocuments(folder='root'){folderNow=folder;let body=folder==='archive'&&!incident.archive?`<div class="archive-lock"><img src="assets/icon-48.ico" width="40" alt=""><h3>Recovery Archive</h3><p>Enter the four-digit handover code.</p><form onsubmit="event.preventDefault();unlockArchive(this.elements.code.value)"><label>Code <input name="code" aria-label="Archive code" inputmode="numeric" maxlength="4" required></label><button class="btn">Unlock</button></form><p id="archiveFeedback" role="status"></p><small>Code attempts are safe. Operations sent the archive handover separately.</small></div>`:folderGrid(folder);windowShow('files',folders[folder],`<div class="explorer-toolbar">${pageButton("openDocuments('root')",'Back')}${pageButton('openJournal()','Case Notes')}${pageButton('openRecovery()','Recovery Tool')}<label style="margin-left:auto">Search <input id="fileSearch" aria-label="Search incident files" oninput="searchFiles(this.value)" placeholder="Name or contents"></label></div><div class="address">Address <input aria-label="Folder address" readonly value="SUPPORT-01\\Incident copies\\${esc(folders[folder])}"></div><div class="explorer-layout"><aside class="explorer-side"><div class="side-box"><strong>Other Places</strong>${Object.entries(folders).map(([id,name])=>`<button onclick="openDocuments('${id}')">${name}</button>`).join('')}</div><div class="side-box"><strong>Collection</strong><p>Read-only copies collected 09:12. Remote PC-04 does not need to be online to inspect these files.</p></div></aside><div class="folder-grid" id="folderContents">${body}</div></div>`,800)}
function searchFiles(q){if(folderNow==='archive'&&!incident.archive)return;$('#folderContents').innerHTML=folderGrid(folderNow,q)}
function unlockArchive(code){if(String(code).trim()==='4827'){incident.archive=true;saveIncident();openDocuments('archive')}else $('#archiveFeedback').textContent='Archive remains locked. Check which reference the handover specifies. No penalty.'}
function fileProperties(name){const suspect=name==='VisitorList_Update.exe';if(suspect)recordRead('B01');windowShow('fileprops','Properties — '+name,`<div class="setting"><h3>${esc(name)}</h3><table class="native-table"><tr><td>Location</td><td>Preserved PC-04 Downloads copy</td></tr><tr><td>Completed</td><td>${suspect?'17 Nov 08:55':'16 Nov 13:00'}</td></tr><tr><td>Acquisition source</td><td>${suspect?'http://meridian-visitor.net/desk':'meridianhouse.org/staff'}</td></tr><tr><td>Publisher</td><td>Not established by this preserved file record</td></tr><tr><td>Action</td><td>Inspection only — executable files cannot run in this game.</td></tr></table>${suspect?pageButton("viewEvidence('B01')",'View download record'):''}</div>`,600)}
function openMail(folder=mailFolder){mailFolder=folder;let list=Object.values(E).filter(e=>e.type==='mail'&&e.folder===folder&&visibleArtifact(e.id)).sort((a,b)=>((incident.triggered[b.id]?.time||b.time||'').localeCompare(incident.triggered[a.id]?.time||a.time||''))||b.id.localeCompare(a.id));if(!list.some(e=>e.id===mailSelected))mailSelected=list[0]?.id;windowShow('mail','Outlook Express — Shared Operations',`<div class="explorer-toolbar">${pageButton('openMail(mailFolder)','Send/Recv')}${pageButton('openJournal()','Case Notes')}${pageButton('openThread(mailSelected)','Thread')}<label style="margin-left:auto">Find <input aria-label="Search mail" placeholder="Subject, sender or text" oninput="searchMail(this.value)"></label><span class="mail-offline">Working Offline</span></div><div class="mail-shell"><aside class="mail-folders"><strong>Operations</strong><p>Shared incident mailbox</p>${['Inbox','Sent Items','Incident copies','Deleted Items','Gala planning','Supplies'].map(f=>`<button class="${f===folder?'selected':''}" onclick="openMail('${f}')">${f} (${Object.values(E).filter(e=>e.type==='mail'&&e.folder===f&&visibleArtifact(e.id)).length})</button>`).join('')}<div class="mail-context">Authorised shared mailbox.<br>Private inboxes are not accessed.</div></aside><div class="mail-main"><div class="mail-list"><table class="native-table"><thead><tr><th>From</th><th>Subject</th><th>Received</th></tr></thead><tbody id="mailRows">${mailRows(list)}</tbody></table></div><div id="mailPreview" class="mail-preview"></div></div></div>`,880);if(mailSelected)renderMailPreview(mailSelected)}
function mailRows(list){return list.map(e=>`<tr tabindex="0" onclick="readMail('${e.id}')" onkeydown="if(event.key==='Enter')readMail('${e.id}')" class="${e.id===mailSelected?'selected':''} ${incident.read.includes(e.id)?'':'unread'}"><td>${esc(e.from.split('<')[0])}</td><td>${esc(e.title)}</td><td>${esc(incident.triggered[e.id]?.time||(e.day==='D'?'':'16 Nov ')+e.time)}</td></tr>`).join('')}
function searchMail(q){const list=Object.values(E).filter(e=>e.type==='mail'&&visibleArtifact(e.id)&&(e.title+' '+e.from+' '+e.body).toLowerCase().includes(q.toLowerCase()));$('#mailRows').innerHTML=mailRows(list)}
function readMail(id){mailSelected=id;recordRead(id);if(!windows.has('mail'))openMail(E[id].folder);else renderMailPreview(id)}
function renderMailPreview(id){const e=E[id];recordRead(id);let body=e.id==='E28'&&incident.ending?{...e,body:e.variants[incident.ending==='full'?'full':incident.ending==='partial'?'partial':'failure']}:e;$('#mailPreview').innerHTML=`<div class="mail-headers"><div><b>From:</b> ${esc(e.from)}</div><div><b>To:</b> ${esc(e.to)}</div><div><b>Subject:</b> ${esc(e.title)}</div><div><b>Original:</b> ${esc(incident.triggered[id]?.time||((e.day==='D'?'17 Nov 2006':e.day==='D−2'?'15 Nov 2006':'16 Nov 2006')+' '+e.time))} · ${id}</div></div><article class="mail-message">${bodyHTML(body)}</article>${footer(id)}`}
function openBrowser(id='B03'){browserPage=id;recordRead(id);const e=E[id];const urls={B01:'History / Completed downloads',B02:'http://meridian-visitor.net/desk',B03:'http://meridianhouse.org/staff',B04:'http://meridianhouse.org/staff/updates',B05:'http://meridianhouse.org/staff/help',B06:'http://meridian-visitor.net/repair'};let body='';if(id==='B01')body=`<h2>Completed downloads — Reception PC-04</h2><table class="native-table"><tr><th>File</th><th>Completed</th><th>Source</th><th>Inspect</th></tr>${[['VisitorList_Update.exe','Today 08:55','meridian-visitor.net/desk'],['badge_layout.pdf','Yesterday 13:00','meridianhouse.org/staff'],['welcome_card.jpg','Yesterday 13:05','meridianhouse.org/staff']].map(([name,time,url])=>`<tr><td>${name}</td><td>${time}</td><td>${url}</td><td><button class="link" onclick="fileProperties('${name}')">Show in folder / Properties</button></td></tr>`).join('')}</table><p>Download completion does not establish installation time.</p>`;else if(id==='B02')body=`<div class="portal-logo">M<span>MERIDIAN VISITOR DESK</span></div><h2>Prepare today’s visitor display</h2><p>${esc(e.body)}</p>${pageButton("fileProperties('VisitorList_Update.exe')",'Inspect preserved download')}<p class="quiet-note">Cached page. No software will run.</p>`;else if(id==='B06')body=`<h2>Automatic repair available</h2><p>Reconnect reception and accept remote unlock.</p>${pageButton('previewRepair()','Preview simulated repair')}<p class="quiet-note">Archived offer. No live connection or password field exists.</p>`;else body=`<h1>Meridian House — ${id==='B03'?'Staff':id==='B04'?'Update notices':'Help'}</h1><div class="intranet-rule"></div><p>${esc(e.body)}</p>${['B03','B04','B05'].filter(x=>x!==id).map(x=>`<p><a href="#" onclick="event.preventDefault();openBrowser('${x}')">${esc(E[x].title)}</a></p>`).join('')}`;windowShow('internet','Microsoft Internet Explorer — Offline Cache',`<div class="explorer-toolbar">${pageButton("openBrowser('B03')",'Home')}${pageButton("openBrowser('B01')",'History / Downloads')}${pageButton("openBrowser('B05')",'Staff Help')}${pageButton(`sourceProperties('${id}')`,'Properties')}</div><form class="address" onsubmit="event.preventDefault();navigateCached(this.elements.url.value)">Address <input name="url" aria-label="Browser address" value="${esc(urls[id])}"><button class="btn">Go</button></form><div class="browser-page"><div class="cached-page">${body}</div></div>${footer(id)}`,820)}
function navigateCached(url){const map={'meridianhouse.org/staff':'B03','meridianhouse.org/staff/updates':'B04','meridianhouse.org/staff/help':'B05','meridian-visitor.net/desk':'B02','meridian-visitor.net/repair':'B06'};let cleaned=url.replace(/^https?:\/\//,'').replace(/\/$/,'');if(map[cleaned])openBrowser(map[cleaned]);else info('Offline support session — that page is not in the saved cache. No live website was opened.')}
function scoreBreakdown(){const c=incident.claims;const pts=[];pts.push([60*(!!c.machine),15*(!!c.machineSource)+15*(!!c.locationSource),40*(contained())]);pts.push([40*(!!c.installer)+25*(!!c.request)+25*(!!c.installTime),20*(!!c.acquisition)+20*(!!c.authenticity)+20*(!!c.causal),15*(!!c.timeline)+15*(incident.quarantined)]);pts.push([40*(!!c.helper)+20*(helperSafe()),20*(!!c.inventory)+20*(!!c.helperPath),20*(!incident.helperRunning)+20*(!incident.helperStartup)]);pts.push([incident.source==='A03'?60:incident.source==='A02'?30:0,20*(!!incident.sourceProof)+20*(incident.mirrorRejected),40*(!!incident.source)]);let a=incident.deltas[0],b=incident.deltas[1],t=incident.deltas[2];const goodA=a?.ref==='MH-231'&&a?.qty===2&&a?.source==='E07',goodB=b?.ref==='MH-209'&&b?.qty===-1&&b?.source==='E08';pts.push([30*goodA+30*goodB+20*(!!incident.source&&(!t||t.qty===0)),10*goodA+10*goodB+20*(t?.qty===0&&t?.source==='E09'),40*(goodA&&goodB&&incident.source==='A03')+20*correctDeltas()]);let checks=incident.test?.revision===incident.revision?incident.test.checks:[];pts.push([40*(!!incident.ending),10*(!!checks[0]?.pass)+10*(!!checks[1]?.pass&&(!!checks[2]?.pass||incident.source==='A02'))+10*(!!checks[3]?.pass)+10*(!!checks[4]?.pass),20*(!!incident.test&&incident.test.revision===incident.revision)+15*(incident.output)+15*(!!incident.ending)]);const core=pts.reduce((a,row)=>a+row.reduce((x,y)=>x+y,0),0);const optional=Math.min(100,incident.optional.length*25);const hints=Object.values(incident.hints).reduce((s,n)=>s+([0,5,15,30][n]||0),0);return {rows:pts,core,optional,hints,penalty:35*incident.unsafe+10*incident.bookingErrors,total:Math.max(0,Math.min(1000,core+optional-35*incident.unsafe-10*incident.bookingErrors-hints))}}
function currentStage(){if(!contained())return 'P01';if(!incident.quarantined)return 'P02';if(!helperSafe())return 'P03';if(!incident.source)return 'P04';if(!correctDeltas())return 'P05';return 'P06'}
function mutate(){incident.revision++;incident.test=null;incident.reviewed=[]}
function actionAllowed(){if(incident.ending){info('This run has ended. You can review evidence and reports, or start a separate replay. No further scored operations are available.');return false}if(paused){info('Resume the support session before applying an operation.');return false}if(incident.minutes>=105&&incident.mode!=='relaxed'){deadlineCheckpoint();return false}return true}
function previewAction(type,data,title,summary,cost=5,unsafe=false){if(!actionAllowed())return;pendingAction={id:Date.now()+'-'+Math.random().toString(36).slice(2),type,data,title,summary,cost,unsafe};windowShow('confirm','Preview — '+title,`<div class="setting"><h3>${esc(title)}</h3><p>${esc(summary)}</p><table class="native-table"><tr><td>Incident time</td><td>${clockTime()} → ${clockTime(555+incident.minutes+cost)} (+${cost} minutes)</td></tr><tr><td>Effect</td><td>${unsafe?'Unsafe action: −35 points; one instability allowance.':'As described above. Originals and archive copies remain preserved.'}</td></tr></table>${incident.minutes+cost>=105&&incident.mode!=='relaxed'?'<p class="action-warning">This reaches the opening deadline. No further recovery steps will be available; hand over the resulting safe state or pause opening.</p>':''}<div class="wizard-footer">${pageButton('commitAction()','Apply')}${pageButton("pendingAction=null;closeWin('confirm')",'Cancel')}</div></div>`,560)}
function commitAction(){if(!pendingAction||operationBusy)return;const op=pendingAction;pendingAction=null;closeWin('confirm');if(!actionAllowed())return;operationBusy=true;incident.minutes+=op.cost;let u=op.unsafe;let d=op.data||{};if(!u&&!(op.type==='changes'&&!d.correct))incident.feedback='';if(u){incident.unsafe++;incident.feedback='The warned operation was unsafe. Its service change was rolled back; the instability and action cost remain recorded.';playSound('critical');}else switch(op.type){case'isolate':incident.isolated='PC-04';incident.claims.machine=true;incident.claims.machineSource=true;incident.claims.locationSource=true;mutate();triggerMail('E23');break;case'quarantine':incident.quarantined=true;triggerMail('E24');triggerMail('E25');break;case'helper':if(d.mode==='both'||d.mode==='stop')incident.helperRunning=false;if(d.mode==='both'||d.mode==='disable')incident.helperStartup=false;mutate();break;case'stage':incident.source=d.source;incident.sourceProof=true;incident.mirrorRejected=d.mirror;incident.deltas=[];mutate();triggerMail('E26');break;case'changes':incident.deltas=d.rows;if(!d.correct){incident.bookingErrors++;incident.feedback='The working list contains changes not supported by the confirmations. This is a booking-service error (−10 points), not a new system-instability event. Review and correct the working ledger.'}mutate();break;case'test':incident.test={revision:incident.revision,checks:verificationChecks(),time:clockTime()};if(incident.test.checks.every(c=>c.pass))triggerMail('E27');break;case'handover':incident.ending=d.outcome;incident.output=d.outcome!=='failure';incident.feedback='';triggerMail('E28');break;}
incident.ledger.push({...op,unsafe:!!u,minute:incident.minutes});saveIncident();operationBusy=false;refreshToolStatus(op.type);syncEffects();if(!op.unsafe){playSound(op.type==='isolate'?'disconnect':op.type==='handover'?'complete':'complete')}showOperationResult(op);if(incident.unsafe>=7&&incident.mode==='standard'&&!incident.ending){incident.ending='integrity-failure';triggerMail('E28');saveIncident();crash();return}if(incident.minutes>=105&&incident.mode==='standard'&&!incident.ending){deadlineCheckpoint();return}clockNotices();}
function showOperationResult(op){windowShow('applied','Operation complete — Duty Support',`<div class="setting"><h3>${esc(op.title)}</h3><p>${op.unsafe?'The warned operation failed safely and has been recorded.':op.type==='changes'?'Changes committed to the separate working copy.':op.type==='test'?'Local checks completed against the current working revision.':op.type==='handover'?'Handover generated. Source evidence remains available for review.':'The simulated support operation has been committed.'}</p><p>Incident clock: ${clockTime()} · Saved before this message appeared.</p><div class="wizard-footer">${pageButton("closeWin('applied');openCase()",'Recovery Log')}${pageButton("closeWin('applied');"+(op.type==='helper'?'openStartup()':op.type==='isolate'?'openNetwork()':op.type==='quarantine'?'openTimeline()':"openRecovery('"+(op.type==='stage'?'changes':op.type==='changes'||op.type==='test'?'verify':'copies')+"')"),'Review result')}</div></div>`,520);if(incident.ending)openReport('R03')}
function clockNotices(){for(const [threshold,msg] of [[45,'10:00: A labelled local or manual list is acceptable. Do not present incomplete records as final.'],[75,'10:30: Thirty incident minutes remain before opening.'],[90,'10:45: Check the remaining recovery actions and their declared costs before committing.']]){if(incident.minutes>=threshold&&!incident.triggered['clock'+threshold]){incident.triggered['clock'+threshold]={time:clockTime()};toast('Operations — opening status',msg)}}saveIncident()}
function deadlineCheckpoint(){windowShow('deadline','Opening deadline — 11:00',`<div class="setting"><h2>Opening-time checkpoint</h2><p>No additional scored recovery operations remain. Reading, notes and source review are still available.</p><p>${fullReady()?'The local list is reconciled and verified. You can hand it over.':partialReady()?'A readable contained list exists, but full readiness is not verified. Use an explicitly labelled manual list.':'There is no safely contained usable list. Pause normal check-in and escalate.'}</p><div class="wizard-footer">${fullReady()?pageButton("finishAtDeadline('full')",'Local-only handover'):''}${partialReady()?pageButton("finishAtDeadline('partial')",'Manual list only'):''}${pageButton("finishAtDeadline('failure')",'Pause opening')}</div></div>`,600)}
function finishAtDeadline(outcome){if(outcome==='full'&&!fullReady()||outcome==='partial'&&!partialReady())return;incident.ending=outcome;incident.output=outcome!=='failure';triggerMail('E28');saveIncident();closeWin('deadline');syncEffects();openReport('R03')}
function noteHypothesis(message){incident.feedback=message;saveIncident();info(message+' No time, score or integrity penalty for this preview.')}
function openNetwork(){windowShow('network','Network Connections — Duty Support',`<div class="explorer-toolbar">SUPPORT-01 · Inspect reception and shared office desks</div><div class="network-body"><p>Disconnect an individual desk from the shared connection. Evidence and mail remain available on this support computer.</p><form onsubmit="event.preventDefault();prepareContainment(this)"><div class="connection-list">${[['PC-02','Finance'],['PC-04','Front reception'],['PC-07','Events'],['PC-09','Staff library']].map(([id,place])=>`<label><input type="radio" name="machine" value="${id}" required><img src="assets/icon-18.ico" alt=""><span><b>${id}</b><small>${place}</small></span><span>${incident.isolated===id?'Isolated':'Connected'}</span></label>`).join('')}</div>${proofSelect('s1','Affected computer evidence')}${proofSelect('s2','Independent location evidence')}<div class="wizard-footer"><button class="btn">Preview disconnect</button>${contained()?pageButton('previewReconnect()','Reconnect PC-04…'):''}</div></form></div>`,700)}
function prepareContainment(form){const p=chosen(form,'s1','s2'),machine=form.elements.machine.value;if(!has(p,'D01')||!has(p,'S02','D08')){noteHypothesis('Attach a source naming the affected computer and an independent register mapping it to its office location. Pinning is not required.');return}if(contained()&&machine==='PC-04'){info('PC-04 is already isolated. No action or charge is needed.');return}previewAction('isolate',{machine},'Disconnect '+machine,machine==='PC-04'?'Disconnect reception only. The support evidence bundle remains online.':'This disconnects an unrelated office desk. Its service would be interrupted; review the incident sources before continuing.',5,machine!=='PC-04')}
function previewReconnect(){if(!contained()){info('Reception is not currently isolated.');return}previewAction('reconnect',{},'Reconnect PC-04','The operating system has not been rebuilt. Reconnecting this untrusted desk is unsafe even if its guest list opens. Keep it isolated for Ellis.',5,true)}
function openTimeline(){const a=incident.chronology;windowShow('timeline','Recovery Log — Installation chronology',`<div class="network-body"><h3>Reconstruct the request and installation</h3><p>A downloaded file and an installed application are different events. Attach original records, then record a supported chronology. Hypotheses and edits are free.</p><form onsubmit="event.preventDefault();submitTimeline(this)"><label class="form-row">Installer filename<input name="file" value="${esc(a.file||'')}" required placeholder="From an inspected download or file"></label><label class="form-row">Originating message<input name="message" value="${esc(a.message||'')}" required placeholder="Source ID, e.g. E01"></label><div class="chronology-grid">${[['requestTime','Request received'],['downloadTime','Download completed'],['installTime','Installation completed'],['damageTime','First failed booking read']].map(([name,label])=>`<label class="form-row">${label}<input name="${name}" value="${esc(a[name]||'')}" placeholder="HH:MM"></label>`).join('')}</div>${proofSelect('requestProof','Message / request source',a.requestProof)}${proofSelect('downloadProof','Download source',a.downloadProof)}${proofSelect('installProof','Installation source',a.installProof)}${proofSelect('noticeProof','Genuine release notice (optional for authenticity credit)',a.noticeProof)}${proofSelect('damageProof','Helper-to-file activity (optional for causal evidence credit)',a.damageProof)}<div class="wizard-footer"><button class="btn">Record hypothesis</button>${incident.claims.timeline&&!incident.quarantined?pageButton('prepareQuarantine()','Preview quarantine'):''}${incident.quarantined?'<span>Installer preserved in quarantine</span>':''}</div></form></div>`,720)}
function normalizeTime(v){let m=v.toLowerCase().trim().match(/^(\d{1,2}):(\d{2})(?:\s*am)?$/);return m?m[1].padStart(2,'0')+':'+m[2]:''}
function submitTimeline(form){const a=Object.fromEntries(new FormData(form));incident.chronology=a;const p=[a.requestProof,a.downloadProof,a.installProof,a.noticeProof,a.damageProof];let c=incident.claims;c.installer=a.file.trim().toLowerCase()==='visitorlist_update.exe';c.request=a.message.trim().toUpperCase()==='E05';c.installTime=normalizeTime(a.installTime)==='08:56';c.acquisition=has(p,'E05')&&has(p,'B01');c.authenticity=has(p,'E06','B04')&&has(p,'E05','B02');c.causal=has(p,'D08')&&readAny('S02');c.timeline=c.installer&&c.request&&c.installTime&&normalizeTime(a.requestTime)==='08:41'&&normalizeTime(a.downloadTime)==='08:55'&&normalizeTime(a.damageTime)==='08:57'&&has(p,'E05')&&has(p,'B01')&&has(p,'S01','D08');saveIncident();if(c.timeline){info('The request, acquisition and installation records support this sequence. You can preserve the installer in quarantine once reception is isolated. This does not stop an already running helper.');openTimeline()}else noteHypothesis('The chronology is still a working hypothesis. Compare the request, completed download and installation records; a camera time may need correction. Correct supporting sources can establish the installation without the camera.');}
function prepareQuarantine(){if(!contained()){info('Isolate the affected desk before quarantining its installer.');return}if(!incident.claims.timeline){info('Record a supported request/download/installation chronology first.');return}if(incident.quarantined){info('Installer already preserved.');return}previewAction('quarantine',{},'Preserve and quarantine installer','Move the inspected installer to a simulated holding folder. Preserve its source and timeline. Installed programs may still be running.',5)}
const startupPrograms=[['Booking Desk','C:\\Program Files\\Booking Desk\\desk.exe','12 Sep'],['Printer Status','C:\\Printer\\status.exe','12 Sep'],['Office Backup','C:\\Office Backup\\backup.exe','12 Sep'],['Visitor List Helper','C:\\Program Files\\Visitor List\\vlhelper.exe','Today 08:58']];
function openStartup(){windowShow('startup','Computer Management — PC-04',`<div class="explorer-toolbar">${pageButton("viewEvidence('D09')",'Event Viewer')}${pageButton('openStartup()','Startup Programs')}${pageButton("viewEvidence('D08')",'Application activity')}</div><div class="network-body"><h3>Programs on reception</h3><p>Stopping a program ends it now. Disabling startup prevents its return at the next login. Quarantining its downloaded installer does neither.</p><form onsubmit="event.preventDefault();prepareHelper(this)"><table class="native-table"><tr><th>Select</th><th>Name / full path</th><th>Added</th><th>Running / startup</th></tr>${startupPrograms.map(([name,path,time],i)=>`<tr><td><input type="radio" name="program" aria-label="${name}" value="${i}" required></td><td>${name}<small class="block">${path}</small></td><td>${time}</td><td>${i===3?(incident.helperRunning?'Running':'Stopped')+' / '+(incident.helperStartup?'Enabled':'Disabled'):'Running / Enabled'}</td></tr>`).join('')}</table><label class="form-row">Operation<select name="mode"><option value="both">Stop now and disable next start</option><option value="stop">Stop now only</option><option value="disable">Disable next start only</option></select></label>${proofSelect('approval','Approved-program inventory')}${proofSelect('identity','Matching installed path / startup record')}<div class="wizard-footer"><button class="btn">Preview change</button></div></form></div>`,790)}
function prepareHelper(form){if(!contained()||!incident.quarantined){info('Inspect freely, but isolate reception and preserve the identified installer before changing its programs.');return}const p=chosen(form,'approval','identity');if(!has(p,'D03')||!has(p,'S04','D08')){noteHypothesis('Compare the approval inventory with the installed path and startup record. A similar name alone is not enough.');return}const selected=Number(form.elements.program.value),mode=form.elements.mode.value;if(selected===3){incident.claims.helper=true;incident.claims.inventory=true;incident.claims.helperPath=true;if(helperSafe()||mode==='stop'&&!incident.helperRunning||mode==='disable'&&!incident.helperStartup){info('That requested state is already applied. No time or score charge.');return}}saveIncident();previewAction('helper',{mode},(mode==='both'?'Stop and disable ':mode==='stop'?'Stop ':'Disable startup: ')+startupPrograms[selected][0],selected===3?'Preserve the installed component while changing only its running/startup state. Reception remains isolated.':'This is approved reception software. Changing it may interrupt legitimate work. Review the full path and approved inventory.',5,selected!==3)}
function countForCurrent(){if(incident.source!=='A03')return null;return 86+incident.deltas.reduce((s,r)=>s+r.qty,0)}
function bookingRows(){return CASE.bookings.map(([ref,label,n])=>({ref,label,base:n,total:n+incident.deltas.filter(r=>r.ref===ref).reduce((s,r)=>s+r.qty,0)}))}
function openRecovery(tab='copies'){caseTab=tab;let body='';if(tab==='copies')body=`<h3>Recovery copies — inspect before staging</h3><p>Copies stay read-only. Staging creates a separate working list; it does not overwrite an archive.</p>${!incident.archive?`<p>The archive is locked. The Operations handover describes its access reference.</p>${pageButton("openDocuments('archive')",'Open archive')}`:`<form onsubmit="event.preventDefault();prepareStage(this)"><table class="native-table"><tr><th>Choose</th><th>Source</th><th>Inspect</th></tr>${[['A02','08:00 Night archive'],['A03','08:45 Reception safety copy'],['A04','09:00 Scheduled mirror']].map(([id,title])=>`<tr><td><input type="radio" name="source" value="${id}" aria-label="${title}" required ${incident.source===id?'checked':''}></td><td>${title}</td><td><button type="button" class="link" onclick="viewEvidence('${id}')">Manifest / content check</button></td></tr>`).join('')}</table>${pageButton("viewEvidence('A01')",'Read copy report')}${proofSelect('condition','Readable contents and transfer condition')}${proofSelect('damage','Evidence of when the source became unreadable')}<label class="check-row"><input type="checkbox" name="mirror"> I have checked whether the newest mirror contains readable data.</label><div class="wizard-footer"><button class="btn">Preview staging</button></div></form>`}`;
if(tab==='changes')body=renderChangeEditor();if(tab==='verify')body=renderVerification();windowShow('recovery','Recovery Tool — PC-04 Working Copy',`<div class="tool-tabs">${[['copies','Recovery copies'],['changes','Pending changes'],['verify','Local test / handover']].map(([id,label])=>`<button class="${tab===id?'active':''}" onclick="openRecovery('${id}')">${label}</button>`).join('')}</div><div class="network-body">${body}</div>`,790)}
function prepareStage(form){if(!stageReady()){info('Before staging a working copy: isolate reception, preserve the installer, stop its matching helper and disable its startup entry. Inspecting copies is still free.');return}const source=form.elements.source.value,p=chosen(form,'condition','damage');if(!has(p,'A01',source)||!has(p,'D08','S02')){noteHypothesis('Attach a copy’s condition report and an independent record establishing when reception data became unreadable.');return}if(source===incident.source){info('This source is already staged.');return}const mirror=form.elements.mirror.checked&&readAny('A01','A04');previewAction('stage',{source,mirror},'Stage '+artifactTitle(source),source==='A04'?'The mirror content check failed. Forcing this unreadable copy is an unsafe operation; it will not replace the current working list.':source==='A02'?'This older readable copy contains 82 guests, but changes from 08:00 to 08:45 cannot be fully reconstructed. A labelled manual-list ending remains possible. Existing working deltas will be cleared.':'Create a separate readable 08:45 working copy with 86 confirmed guests. Existing working deltas will be cleared; originals are preserved.',source==='A04'?5:10,source==='A04')}
function renderChangeEditor(){if(!incident.source)return '<h3>No staged copy</h3><p>Inspect and stage a readable recovery copy first.</p>';if(incident.source==='A02')return `<h3>08:00 baseline — unresolved interval</h3><p>The readable source contains 82 guests. The supplied later messages do not reconstruct every change made between 08:00 and 08:45. A total of 87 cannot be certified from this source.</p>${pageButton("openRecovery('copies')",'Compare a later copy')}${pageButton("openRecovery('verify')",'Prepare manual handover')}`;return `<h3>Reconcile confirmed changes after 08:45</h3><p>Baseline: 86 confirmed guests. Enter the booking reference and actual guest adjustment. A plausible total alone does not establish correct bookings.</p><form id="deltaForm" onsubmit="event.preventDefault();previewDeltas(this)">${[0,1].map((i)=>{const r=incident.deltas[i]||{};return `<fieldset class="delta-row"><legend>Confirmed change ${i+1}</legend><label>Booking <select name="ref${i}"><option value="">Select a booking…</option>${CASE.bookings.map(([ref,label])=>`<option value="${ref}" ${r.ref===ref?'selected':''}>${ref} — ${label}</option>`).join('')}</select></label><label>Guest adjustment <input type="number" name="qty${i}" min="-20" max="20" required value="${r.qty??''}" placeholder="e.g. +1 or -1"></label>${proofSelect('proof'+i,'Confirmation source',r.source)}</fieldset>`}).join('')}<fieldset class="delta-row"><legend>Pending enquiry ENQ-0855</legend><label>Action<select name="enquiry"><option value="0">Hold — do not add guests</option><option value="6" ${incident.deltas[2]?.qty===6?'selected':''}>Add six to confirmed list</option></select></label>${proofSelect('enquiryProof','Optional explicit hold evidence',incident.deltas[2]?.source)}</fieldset><div class="wizard-footer"><button class="btn">Preview resulting list</button></div></form>${incident.deltas.length?`<p>Current working total: <b>${countForCurrent()}</b></p>${pageButton("openBookingDesk()",'Open current Booking Desk')}`:''}`}
function previewDeltas(form){const rows=[0,1].map(i=>({ref:form.elements['ref'+i].value,qty:Number(form.elements['qty'+i].value),source:form.elements['proof'+i].value}));rows.push({ref:'ENQ-0855',qty:Number(form.elements.enquiry.value),source:form.elements.enquiryProof.value});if(rows.slice(0,2).some(r=>!r.ref||!r.source)||rows[0].ref===rows[1].ref){noteHypothesis('Attach a source for each of two distinct booking changes. Reading or correcting this preview is free.');return}const goodA=rows.some(r=>r.ref==='MH-231'&&r.qty===2&&r.source==='E07'),goodB=rows.some(r=>r.ref==='MH-209'&&r.qty===-1&&r.source==='E08');let ordered=rows;if(goodA&&goodB)ordered=[rows.find(r=>r.ref==='MH-231'),rows.find(r=>r.ref==='MH-209'),rows[2]];const correct=goodA&&goodB&&rows[2].qty===0;let total=86+rows.reduce((s,r)=>s+r.qty,0);pendingAction={type:'changes',data:{rows:ordered,correct},title:'Apply booking reconciliation',cost:5,summary:correct?'Apply the supported confirmed changes to the working copy.':'The proposed rows or enquiry are not supported by the cited confirmations. Applying anyway records a booking-service error (−10 points), not system damage.'};windowShow('deltaPreview','Preview — Booking changes',`<div class="network-body"><h3>Working list preview</h3><table class="native-table"><tr><th>Reference</th><th>Adjustment</th><th>Source</th></tr>${rows.map(r=>`<tr><td>${esc(r.ref)}</td><td>${r.qty>0?'+':''}${r.qty}</td><td>${r.source||'None'}</td></tr>`).join('')}</table><p>86 ${rows.map(r=>(r.qty<0?'− '+Math.abs(r.qty):'+ '+r.qty)).join(' ')} = <b>${total}</b></p><p>${esc(pendingAction.summary)}</p><div class="wizard-footer">${pageButton('confirmDeltaApplication()','Apply to working copy')}${pageButton("pendingAction=null;closeWin('deltaPreview')",'Edit / Cancel')}</div></div>`,650)}
function confirmDeltaApplication(){const op=pendingAction;if(!op)return;closeWin('deltaPreview');if(JSON.stringify(incident.deltas)===JSON.stringify(op.data.rows)){pendingAction=null;info('These changes are already applied; no additional charge.');return}previewAction('changes',op.data,op.title,op.summary,5)}
function verificationChecks(){return [{name:'Booking file opens locally',pass:!!incident.source},{name:'Readable original recovery source',pass:['A02','A03'].includes(incident.source)},{name:'Confirmed booking rows reconcile',pass:correctDeltas()},{name:'Matching helper stopped and startup disabled',pass:helperSafe()},{name:'Reception remains isolated',pass:contained()}]}
function renderVerification(){let checks=verificationChecks();return `<h3>Local verification and service handover</h3><p>Restoring a list does not prove the operating system is trustworthy. Keep PC-04 disconnected for Ellis’s rebuild.</p><table class="native-table"><tr><th>Free preview of prerequisites</th><th>State</th></tr>${checks.map(c=>`<tr><td>${c.name}</td><td>${c.pass?'Ready to test':'Not ready'}</td></tr>`).join('')}</table><div class="toolbar-actions">${pageButton('prepareTest()','Run local test (+5 min)')}${pageButton('openBookingDesk()','Review booking rows')}${pageButton("openReport('R02')",'Saved test report')}</div>${incident.test?`<p>Last test: ${incident.test.time} · ${incident.test.revision===incident.revision?'Current working revision':'Out of date'}</p>`:''}<h3>Choose an honest handover</h3><div class="handover-options">${pageButton("prepareHandover('full')",'Local desk ready, keep isolated')}${pageButton("prepareHandover('partial')",'Manual list only')}${pageButton("prepareHandover('failure')",'Pause opening and escalate')}</div>`}
function prepareTest(){if(!contained()||!incident.source||!helperSafe()){info('The free preview shows unmet prerequisites. Contain reception, stop and disable its helper, and stage a readable copy before running a local test.');return}if(incident.test?.revision===incident.revision){info('A test report for this working revision already exists. Reopening it is free.');openReport('R02');return}previewAction('test',{},'Run local verification','Run five checks on the current working revision. A failed reconciliation can be corrected without damaging the source copies.',5)}
function prepareHandover(outcome){if(outcome==='full'&&!fullReady()){info('Full readiness is not established. Use the 08:45 source, reconcile the actual booking rows, run a passing current test, and inspect both changed bookings. Reception must remain isolated with its helper stopped and disabled.');return}if(outcome==='partial'&&!partialReady()){info('A manual list requires a readable staged copy plus containment and a stopped/disabled helper. Otherwise pause opening and escalate.');return}previewAction('handover',{outcome},outcome==='full'?'Generate local desk list and rebuild handover':outcome==='partial'?'Generate labelled manual list':'Pause check-in and escalate',outcome==='full'?'Supply the verified 87-guest list for local use. PC-04 remains isolated; Ellis receives the rebuild requirement.':outcome==='partial'?'Label the baseline and unresolved changes clearly. Direct discrepancies to Mara; do not refuse guests solely because this incomplete list omits them.':'Staff will not use the unverified list. Evidence and notes remain preserved for further review.',5)}
function openBookingDesk(){if(!incident.source){windowShow('remote','PC-04 — Remote Reception Session',`<div class="remote-caption">Preserved damaged reception session · SUPPORT-01 remains healthy</div><div class="remote-desktop"><div class="remote-warning"><div class="capture-title">Booking Desk</div><div class="error-body"><span class="error-sign"></span><p>gala.book cannot be opened — file locked or unreadable.<br>Work on a separate recovery copy.</p></div></div><div id="remoteErrors"></div><div class="remote-taskbar">PC-04 / Front reception · ${clockTime()}</div></div><div class="wizard-footer">${pageButton('dismissRemoteErrors()','Dismiss session errors')}${pageButton('openCase()','Bring support tools forward')}</div>`,760);syncEffects();return}windowShow('bookings','Booking Desk — Local Working Copy',`<div class="booking-app"><div class="booking-header"><h2>MERIDIAN HOUSE</h2><p>PC-04 local working copy · Network isolated: ${contained()?'Yes':'No'}</p></div><div class="booking-total"><span>${incident.source==='A03'?'Confirmed guests in current working list':'Historical baseline — later interval unresolved'}</span><strong>${incident.source==='A03'?countForCurrent():82}</strong><small>${incident.source==='A03'?'08:45 baseline with separately applied changes':'08:00 baseline. Do not certify a final opening count.'}</small></div>${incident.source==='A03'?`<table class="native-table"><tr><th>Reference</th><th>Party</th><th>Baseline</th><th>Working count</th><th>Inspect</th></tr>${bookingRows().map(r=>`<tr><td>${r.ref}</td><td>${r.label}</td><td>${r.base}</td><td>${r.total}</td><td><button class="link" onclick="reviewBooking('${r.ref}')">Open row</button></td></tr>`).join('')}</table>`:'<p>No complete later row reconstruction is available for this historical manifest.</p>'}<div class="wizard-footer">${pageButton("openRecovery('changes')",'Change ledger')}${pageButton("openRecovery('verify')",'Local test / handover')}</div></div>`,760)}
function reviewBooking(ref){const r=bookingRows().find(r=>r.ref===ref);if(!r)return;if(!incident.reviewed.includes(ref))incident.reviewed.push(ref);saveIncident();windowShow('bookingrow','Booking '+ref,`<div class="setting"><h3>${ref} — ${r.label}</h3><p>08:45 baseline: ${r.base}<br>Current working party size: <b>${r.total}</b></p><p>Sources: ${incident.deltas.filter(d=>d.ref===ref).map(d=>`${d.source} (${d.qty>0?'+':''}${d.qty})`).join(', ')||'No later changes applied'}</p><div class="wizard-footer">${pageButton("closeWin('bookingrow')",'Close')}${pageButton("openRecovery('verify')",'Handover')}</div></div>`,480)}
const HINTS={P01:['Find a source that identifies the desk showing the booking warning.','Compare that machine label with the independent office register.','The warning names PC-04; D01 places PC-04 at front reception.'],P02:['Compare the installation request with the genuine update notice.','A request, a completed download, an installation and a file failure have different timestamps.','E05 → B01 → S01/D08. Request 08:41; download 08:55; install 08:56; first failure 08:57.'],P03:['A downloaded installer and an installed program are different things.','Compare the full installed path and the approval inventory. Check whether the matching helper is still running.','Visitor List Helper at C:\\Program Files\\Visitor List\\vlhelper.exe must be stopped now and disabled for next start.'],P04:['The archive handover specifies a particular reference, not a guest number.','Compare readable contents rather than transfer success. An older readable source may be safer.','The venue reference ends in 4827. A03 is the 08:45 readable copy; the 09:00 mirror copied damaged contents.'],P05:['Only confirmed changes after the source copy belong in your working list.','A single-guest cancellation is not cancellation of the whole party. A request is not a booking.','MH-231: add 2 with E07. MH-209: remove 1 with E08. Hold ENQ-0855 with E09. Total 87.'],P06:['A plausible guest count is not the same as verified service.','Run the local test, inspect both changed rows and keep the workstation isolated.','Use the reconciled A03 list; pass five checks; open MH-231 and MH-209; choose Local desk ready, keep isolated.']};
function unlockHint(puzzle){const old=incident.hints[puzzle]||0;if(old>=3){openHints(puzzle);return}const level=old+1,cost=[0,5,10,15][level];windowShow('hintconfirm','Help — '+appNames[puzzle],`<div class="setting"><h3>${level===1?'A lead':level===2?'A stronger lead':'Solution walkthrough'}</h3><p>Unlocking this hint costs ${cost} score points. Reading it again is free. It does not advance incident time or affect system integrity.</p><div class="wizard-footer">${pageButton(`acceptHint('${puzzle}',${level})`,'Unlock hint')}${pageButton("closeWin('hintconfirm')",'Cancel')}</div></div>`,450)}
function acceptHint(id,level){if((incident.hints[id]||0)>=level){openHints(id);return}incident.hints[id]=level;saveIncident();closeWin('hintconfirm');openHints(id)}
function openHints(puzzle=currentStage()){let n=incident.hints[puzzle]||0;windowShow('hints','Recovery Help — '+appNames[puzzle],`<div class="setting"><h3>${appNames[puzzle]}</h3>${n?HINTS[puzzle].slice(0,n).map((t,i)=>`<p><b>Level ${i+1}</b><br>${esc(t)}</p>`).join(''):'<p>No hints unlocked for this task.</p>'}<div class="wizard-footer">${n<3?pageButton(`unlockHint('${puzzle}')`,'Unlock '+(n+1)+'…'):''}${pageButton("closeWin('hints')",'Close')}</div></div>`,550)}
function openCase(){const p=currentStage();const status={P01:contained(),P02:incident.quarantined,P03:helperSafe(),P04:!!incident.source,P05:correctDeltas(),P06:!!incident.ending};windowShow('game','Recovery Log — Duty Support / SUPPORT-01',`<div class="support-heading"><img src="assets/icon-35.ico" alt=""><div><b>Meridian House · The Missing Morning</b><span>Authorised support session · 17 November 2006</span></div></div><div class="network-body"><p>${incident.ending?'Run ended. Evidence and tools remain available for review.':'Inspect first, preview practical changes, then apply a supported action. You may explore in any order.'}</p><table class="native-table recovery-checklist"><tr><th>Support task</th><th>State</th><th>Open tool</th></tr>${Object.entries(appNames).map(([id,title])=>`<tr><td>${id} · ${title}</td><td>${status[id]?'Completed':id===p?'Current lead':'Pending / inspect freely'}</td><td><button class="link" onclick="openPuzzle('${id}')">Open</button> · <button class="link" onclick="openHints('${id}')">Help</button></td></tr>`).join('')}</table>${incident.feedback?`<p class="case-feedback">${esc(incident.feedback)}</p>`:''}<div class="incident-strip">Incident clock <b>${clockTime()}</b> · Applies actions only · ${incident.mode==='relaxed'?'Relaxed mode: no cutoff':'Opening 11:00'}<br>SUPPORT-01 stays healthy. Reception: ${contained()?'isolated':'not contained'} · ${integrity()}% stability abstraction</div><div class="toolbar-actions">${pageButton('openJournal()','Case Notes')}${pageButton('openMail()','Operations Mail')}${pageButton('openScore()','Score details')}${pageButton('openBriefing()','Handover / guidance')}${pageButton('openSettings()','Accessibility / sound')}</div></div>`,780)}
function openPuzzle(id){({'P01':openNetwork,'P02':openTimeline,'P03':openStartup,'P04':()=>openRecovery('copies'),'P05':()=>openRecovery('changes'),'P06':()=>openRecovery('verify')})[id]()}
function openJournal(){windowShow('journal','Case Notes — Notepad',`<div class="notebook-tabs">${pageButton('openJournal()','Notes / Findings')}${pageButton('openOptional()','Record optional deduction')}${pageButton('openTimeline()','Chronology')}</div><div class="journal-body"><p>Sources can support actions directly after inspection. Saving findings here is a convenience, not a mandatory collection task.</p><textarea aria-label="Working notes" placeholder="What agrees? What contradicts the first account? What remains uncertain?" oninput="incident.notes=this.value;saveIncident()">${esc(incident.notes)}</textarea><h4>Saved findings (${incident.pinned.length})</h4>${incident.pinned.length?`<table class="native-table"><tr><th>Source</th><th>Finding</th><th>Open</th></tr>${incident.pinned.map(id=>`<tr><td>${id}</td><td>${esc(artifactTitle(id))}</td><td><button class="link" onclick="viewEvidence('${id}')">Review</button></td></tr>`).join('')}</table>`:'<p>No saved findings yet.</p>'}<h4>Inspected sources</h4><div class="source-link-list">${incident.read.map(id=>`<button class="link" onclick="viewEvidence('${id}')">${id} — ${esc(artifactTitle(id))}</button>`).join('')}</div><p class="quiet-note">Notes save locally for this profile. Sources remain read-only after any ending.</p></div>`,700)}
function openOptional(){windowShow('optional','Case Notes — Record a deduction',`<div class="network-body"><h3>Optional explanations</h3><p>These are not required for recovery. A supported explanation earns 25 points once. Guessing or revising a hypothesis is free.</p><form onsubmit="event.preventDefault();recordOptional(this)"><label class="form-row">Deduction<select name="claim" onchange="document.querySelector('#cameraTimeRow').hidden=this.value!=='camera'"><option value="camera">Correct the corridor camera time</option><option value="welcome">Distinguish the approved events program</option><option value="invoice">Limit what the invoice trail establishes</option><option value="repair">Decline the unsolicited repair offer</option></select></label><label class="form-row" id="cameraTimeRow">Correct office time for camera 08:48<input name="time" placeholder="HH:MM"></label><label class="form-row">Conclusion<select name="conclusion"><option value="limited">Evidence has a limited, specific conclusion</option><option value="accuse">This identifies the person responsible for the attack</option></select></label>${proofSelect('s1','Source one')}${proofSelect('s2','Independent supporting source')}<button class="btn">Record supported finding</button></form><p>Accepted optional findings: ${incident.optional.join(', ')||'None'}</p></div>`,650)}
function recordOptional(form){const type=form.elements.claim.value,p=chosen(form,'s1','s2');let valid=form.elements.conclusion.value==='limited';valid=valid&&(type==='camera'?has(p,'S03')&&has(p,'D05')&&normalizeTime(form.elements.time.value)==='08:56':type==='welcome'?has(p,'D06')&&has(p,'S05','E14'):type==='invoice'?has(p,'D07')&&has(p,'E04','E17'):has(p,'E11','B06')&&has(p,'D02','B05'));if(!valid){noteHypothesis('That explanation needs relevant independent sources and a conclusion no stronger than the evidence supports. A camera frame or a session account does not identify who installed software.');return}if(!incident.optional.includes(type))incident.optional.push(type);saveIncident();info('Supported optional deduction recorded. This discovery is worth 25 points once, regardless of how many sources or windows you open.')}
function openScore(){const s=scoreBreakdown();const grade=s.total>=900?'Meticulous':s.total>=750?'Well supported':s.total>=550?'Recovered with gaps or assistance':'Substantial unresolved work';windowShow('score','Support Report — Score Details',`<div class="network-body"><h3>${s.total} / 1000 — ${grade}</h3><p>Service status: ${incident.ending||'Investigation in progress'} · ${incident.mode} mode. Score does not override the actual service outcome.</p><table class="native-table"><tr><th>Puzzle</th><th>Decision</th><th>Evidence</th><th>Completion</th></tr>${s.rows.map((row,i)=>`<tr><td>${'P0'+(i+1)}</td>${row.map(x=>'<td>'+x+'</td>').join('')}</tr>`).join('')}<tr><td>Core / maximum 900</td><td colspan="3">${s.core}</td></tr><tr><td>Optional / maximum 100</td><td colspan="3">${s.optional}</td></tr><tr><td>Unsafe actions</td><td colspan="3">${incident.unsafe} × −35</td></tr><tr><td>Booking service errors</td><td colspan="3">${incident.bookingErrors} × −10</td></tr><tr><td>Unlocked hints</td><td colspan="3">−${s.hints}</td></tr></table><p>Score = accepted core + optional discoveries − unsafe penalties − booking errors − hint costs, clamped to 0–1000. No reading-speed, elapsed-time or click-count bonus.</p><h4>Committed action ledger</h4><table class="native-table"><tr><th>Time</th><th>Action</th><th>Cost</th></tr>${incident.ledger.map(op=>`<tr><td>${clockTime(555+op.minute)}</td><td>${esc(op.title)}${op.unsafe?' — unsafe':''}</td><td>${op.cost} min</td></tr>`).join('')}</table></div>`,760)}
function openReport(id){let body='';if(id==='R01')body=`<h3>Working change ledger</h3><p>Source: ${incident.source?artifactTitle(incident.source):'No source staged'} · Revision ${incident.revision}</p><table class="native-table"><tr><th>Reference</th><th>Change</th><th>Source</th></tr>${incident.deltas.map(d=>`<tr><td>${d.ref}</td><td>${d.qty}</td><td>${d.source||'Not attached'}</td></tr>`).join('')}</table><p>Current total: ${countForCurrent()??'Unknown beyond historical baseline'}</p>`;else if(id==='R02')body=incident.test?`<h3>Local verification — ${incident.test.time}</h3><p>Tested revision ${incident.test.revision}. ${incident.test.revision===incident.revision?'Current report.':'Out of date — working state changed.'}</p><table class="native-table"><tr><th>Check</th><th>Result</th></tr>${incident.test.checks.map(c=>`<tr><td>${c.name}</td><td>${c.pass?'Passed':'Failed'}</td></tr>`).join('')}</table><p>Local usability is not proof of malware eradication. Keep reception isolated pending rebuild.</p>`:'<p>No local test has been run.</p>';else if(!incident.ending)body='<p>No handover has been generated. Review the local test and choose an honest service status.</p>';else{const s=scoreBreakdown();body=`<div class="briefing-letterhead">MERIDIAN HOUSE <small>SUPPORT HANDOVER — ${esc(incident.ending.toUpperCase())}</small></div><h2>${incident.ending==='full'?'Reception is ready locally.':incident.ending==='partial'?'A labelled manual list is available.':'Normal check-in is paused.'}</h2><p>${incident.ending==='full'?'The 08:45 safety copy contained 86 guests. The two confirmed additions and single cancellation were applied to the actual bookings. The list now contains 87 confirmed guests.':incident.ending==='partial'?'Use the readable '+(incident.source==='A02'?'08:00 historical baseline (82 guests)':'08:45 working list')+'. Later changes or verification remain incomplete. Send discrepancies to Mara; do not use this list to reject guests.':'No verified usable service handover was completed. Evidence copies and notes remain available to Ellis.'}</p><p><b>PC-04 must remain isolated. Ellis must rebuild the operating system before network return.</b></p><h3>What the records establish</h3><p>The request led to the downloaded installer, installed at 08:56. The matching helper accessed and changed the booking file before its 08:57 read failure and was registered for startup at 08:58. The records strongly connect the installation to the incident. They do not identify the controller of the external site or prove whether information was taken.</p><h3>Explained after investigation</h3><p>The corridor camera was eight minutes slow and cannot identify who clicked Install. Welcome Loop was approved on PC-07 the previous day. The supplied invoice trail concerns Finance PC-02. The newest mirror copied damaged contents; successful copying did not make it a usable booking source.</p><p>${s.total} / 1000 · ${incident.mode} mode · ${incident.unsafe} unsafe actions · ${incident.bookingErrors} booking errors · Incident time ${clockTime()}</p><div class="toolbar-actions">${pageButton('openScore()','Full score breakdown')}${pageButton('openBookingDesk()','Desk list')}${pageButton("readMail('E28')",'Operations reply')}${pageButton('restartIncident()','Replay…')}</div>`}windowShow('report',artifactTitle(id)+' — Duty Support',`<div class="network-body">${body}</div>`,790)}
function openBriefing(){windowShow('briefing','Coordinator Handover — Duty Support',`<div class="briefing"><div class="briefing-letterhead">MERIDIAN HOUSE <small>OPERATIONS / AUTHORISED INCIDENT SUPPORT</small></div><h2>The Missing Morning</h2><p><b>17 November 2006 · 09:15 · SUPPORT-01</b></p><p>Reception’s booking list stopped opening before nine. Doors open at eleven. Staff can manage a queue; they cannot confidently send guests away because a damaged list says they are missing.</p><p>You are using a healthy support computer and the shared Operations mailbox. Staff supplied read-only incident copies at 09:12. The reception computer can be isolated while you continue reading mail, screenshots and records here.</p><ol><li>Explore Outlook Express, My Documents and the offline browser cache.</li><li>Compare original sources, record hypotheses and preview practical recovery actions.</li><li>Keep evidence preserved, recover a usable guest list and provide an honest handover.</li></ol><p>The incident clock advances only when you apply an operation. Reading, comparing, notes, code attempts and hypotheses cost no time. Each action preview shows its cost. Unsafe committed system operations consume one of seven instability allowances; booking mistakes affect score and service without damaging the system.</p><p>Standard mode has an 11:00 action-clock cutoff. Relaxed mode removes the cutoff and harmful-action lockout. </p><p class="quiet-note">Local browser game. No personal files, private mail or real computer settings are accessed. The previous edition’s local saves are kept separately from this revised case.</p><div class="wizard-footer">${pageButton("closeWin('briefing');openMail('Inbox')",'Read Operations mail')}${pageButton("closeWin('briefing');openCase()",'Open Recovery Log')}</div></div>`,700)}
function previewRepair(){previewAction('repair',{},'Unverified automatic repair','This unverified offer would reconnect the untrusted reception system. Reading this page is safe. Applying the warned reconnection is unsafe. No password or live connection is involved.',5,true)}
let audioPrefs={enabled:true,system:.35,effects:.2};try{audioPrefs={...audioPrefs,...JSON.parse(localStorage.getItem('deadline:audio-v2')||'{}')}}catch{}
const playingAudio=new Set();let lastSoundAt=0;
const SOUND_MAP={logon:'logon',logoff:'logoff',startup:'startup',shutdown:'shutdown',error:'error',critical:'hardwarefail',notification:'notify',warning:'exclamation',click:'start',complete:'ding',disconnect:'remove',connect:'insert'};
function playSound(event,force=false){if(!audioPrefs.enabled||paused||document.hidden)return;const name=SOUND_MAP[event];if(!name)return;if(['error','critical','notification','warning'].includes(event)&&Date.now()-lastSoundAt<900&&!force)return;lastSoundAt=Date.now();const a=new Audio('assets/audio/'+name+'.wav');a.volume=['logon','logoff','startup','shutdown'].includes(event)?audioPrefs.system:audioPrefs.effects;playingAudio.add(a);a.onended=()=>playingAudio.delete(a);a.play().catch(()=>playingAudio.delete(a))}
function stopAudio(){playingAudio.forEach(a=>{a.pause();a.currentTime=0});playingAudio.clear()}
function saveAudio(){localStorage.setItem('deadline:audio-v2',JSON.stringify(audioPrefs));sound=audioPrefs.enabled;$('#audio').textContent=audioPrefs.enabled?'♫':'♪'}
beep=function(type){playSound(type==='success'?'complete':'error')};
const originalToast=toast;toast=function(title,message){originalToast(title,message);playSound(/warning|error|risk/i.test(title)?'warning':'notification')};
function openSettings(){windowShow('settings','Control Panel — Sounds and Accessibility',`<div class="network-body"><h3>Sounds and Audio Devices</h3><p>Windows XP audio from your uploaded sound pack. No external audio service is used.</p><label class="check-row"><input type="checkbox" ${audioPrefs.enabled?'checked':''} onchange="audioPrefs.enabled=this.checked;if(!this.checked)stopAudio();saveAudio()"> Enable Windows sounds</label><label class="form-row">Login, logoff and shutdown volume<input type="range" min="0" max="1" step=".05" aria-label="System sound volume" value="${audioPrefs.system}" oninput="audioPrefs.system=Number(this.value);saveAudio()"></label><label class="form-row">Notifications and errors volume<input type="range" min="0" max="1" step=".05" aria-label="Effects volume" value="${audioPrefs.effects}" oninput="audioPrefs.effects=Number(this.value);saveAudio()"></label><div class="sound-tests">${[['logon','Logon'],['logoff','Logoff'],['startup','Startup'],['shutdown','Shutdown'],['error','Error'],['warning','Exclamation'],['notification','New mail']].map(([id,label])=>pageButton(`playSound('${id}',true)`,label)).join('')}</div><h3>Accessibility</h3><label class="check-row"><input type="checkbox" ${incident.access.reduced?'checked':''} onchange="incident.access.reduced=this.checked;saveIncident();applyAccessibility()"> Reduced motion — remove remote trails and animated room playback</label><label class="check-row"><input type="checkbox" ${incident.access.large?'checked':''} onchange="incident.access.large=this.checked;saveIncident();applyAccessibility()"> Larger readable application text</label><label class="check-row"><input type="checkbox" ${incident.mode==='relaxed'?'checked disabled':''} onchange="enableRelaxed()"> Relaxed mode — no deadline or instability lockout (permanent for this run)</label><p class="quiet-note">All visual evidence has a transcript. Tab/Enter and Open commands provide alternatives to dragging and double-clicking. Sound is never required for a clue.</p><div class="toolbar-actions">${pageButton('openNetwork()','Network Connections')}${pageButton('openStartup()','Computer Management')}${pageButton('restartIncident()','Restart case…')}</div></div>`,710)}
function applyAccessibility(){desktop.classList.toggle('large-text',!!incident.access.large);desktop.classList.toggle('reduced-motion',!!incident.access.reduced);if(incident.access.reduced)document.querySelectorAll('.cctv-scene').forEach(el=>el.classList.remove('playing'))}
function enableRelaxed(){incident.mode='relaxed';saveIncident();syncEffects();info('Relaxed mode enabled for this run. Score penalties remain visible, but there is no opening cutoff or seven-action lockout.')}
function stopCascade(){clearTimeout(cosmeticTimer);cosmeticTimer=null;clearTimeout(cascadeTimer);cascadeTimer=null;document.querySelectorAll('.corruption-trail').forEach(el=>el.remove())}
function dismissRemoteErrors(){const el=$('#remoteErrors');if(el)el.innerHTML='';document.querySelectorAll('.corruption-trail').forEach(el=>el.remove())}
function syncEffects(){stopCascade();desktop.classList.remove('infected','severe','glitch');state.wrong=incident.unsafe;state.solved=!!incident.ending;$('#trayShield').innerHTML=`<img class="xp-icon" src="assets/${incident.ending==='full'?'icon-16.ico':'icon-48.ico'}" alt="">`;if(incident.ending){dismissRemoteErrors();return}if(paused||document.hidden)return;const cap=incident.unsafe>=5?4:incident.unsafe>=3?3:2;const host=$('#remoteErrors');if(host&&incident.unsafe>0){const n=document.createElement('div');n.className='remote-error';n.style.left=(15+incident.unsafe*19)%240+'px';n.style.top=(20+incident.unsafe*11)%130+'px';n.innerHTML=`<div class="capture-title">PC-04 — Application Error</div><p>${incident.unsafe===6?'One more unsafe operation ends this recovery session.':'Reception application is not responding.'}</p><button class="btn" onclick="this.parentElement.remove()">OK</button>`;host.append(n);while(host.children.length>cap)host.firstChild.remove()}if(incident.unsafe>=3)cosmeticTimer=setTimeout(()=>{if($('#remoteErrors')){syncEffects();playSound('error')}},45000)}
syncCascade=syncEffects;effects=syncEffects;errorPopup=function(){openBookingDesk();syncEffects()};
crash=function(){stopCascade();windowShow('remote','PC-04 — Remote Reception Session Failed',`<div class="remote-blue"><p>A problem has been detected and the PC-04 recovery session has been shut down.</p><p>RECOVERY_ACTION_LIMIT_REACHED</p><p>Seven unsafe operations were committed. SUPPORT-01, the notebook and preserved source bundle remain available.</p><p>*** STOP: 0x00000007</p></div><div class="wizard-footer">${pageButton('openReport(\'R03\')','Review incident')}${pageButton('openJournal()','Case Notes')}${pageButton('restartIncident()','Restart…')}</div>`,760)};
recover=function(){openCase()};
function restartIncident(){windowShow('restartcase','Restart revised investigation?',`<div class="setting"><h3>Start this case again?</h3><p>This replaces progress for this profile in the revised edition. Other profiles and earlier-edition saves remain untouched.</p><div class="wizard-footer">${pageButton('beginFreshIncident()','Restart case')}${pageButton("closeWin('restartcase')",'Cancel')}</div></div>`,460)}
function beginFreshIncident(){stopCascade();[...windows.keys()].forEach(closeWin);incident=initialIncident();saveIncident();applyAccessibility();openBriefing()}
function openSecurity(){windowShow('security','Windows Security Center — Local Incident',`<div class="scanhead"><img src="assets/icon-48.ico" width="40" alt=""><div><h2>Reception incident status</h2><span>Support host healthy · Remote PC-04 remains untrusted until rebuilt</span></div></div><div class="network-body"><table class="native-table"><tr><td>Reception network</td><td>${contained()?'Isolated':'Not yet contained'}</td></tr><tr><td>Installer preserved</td><td>${incident.quarantined?'Yes':'No'}</td></tr><tr><td>Installed helper</td><td>${incident.helperRunning?'Running':'Stopped'} / ${incident.helperStartup?'Startup enabled':'Startup disabled'}</td></tr><tr><td>System instability allowance</td><td>${incident.unsafe} unsafe actions / ${incident.mode==='relaxed'?'Relaxed: no lockout':'7 triggers session failure'}</td></tr><tr><td>Integrity abstraction</td><td>${integrity()}% (game measure, not a forensic guarantee)</td></tr><tr><td>Service status</td><td>${incident.ending||'Under investigation'}</td></tr></table><div class="toolbar-actions">${pageButton('openBookingDesk()','Reception session')}${pageButton('openCase()','Recovery Log')}${pageButton('openScore()','Score details')}</div></div>`,690)}
openApp=function(id){$('#startmenu').hidden=true;const handlers={game:openCase,files:()=>openDocuments('root'),mail:()=>openMail(),journal:openJournal,internet:()=>openBrowser(),network:openNetwork,startup:openStartup,settings:openSettings,security:openSecurity,help:openBriefing,bookings:openBookingDesk,cctv:openCCTV,score:openScore,computer:()=>{windowShow('computer','My Computer — SUPPORT-01',`<div class="computer-body"><h3>Healthy support workstation</h3><p>Authorised Operations mailbox and read-only staff-supplied incident copies. Reception PC-04 is a separate simulated session.</p><div class="control-grid"><button onclick="openDocuments('root')"><img src="assets/folder.png" alt="">Incident copies</button><button onclick="openNetwork()"><img src="assets/icon-18.ico" alt="">Network Connections</button><button onclick="openStartup()"><img src="assets/icon-36.ico" alt="">Computer Management</button><button onclick="openRecovery()"><img src="assets/icon-8.ico" alt="">Recovery Tool</button><button onclick="openBookingDesk()"><img src="assets/icon-16.ico" alt="">Remote PC-04</button></div></div>`,680)},recycle:()=>windowShow('recycle','Recycle Bin',`<div class="notepad">old welcome wording.txt\n15 November 2006, 09:00\n\nWelcome to Meridian House\n\nDraft wording only. No incident evidence.</div>`,480)};if(handlers[id])handlers[id]();else xpOpenApp(id)};
game=openCase;security=openSecurity;welcome=openBriefing;startPractice=restartIncident;
const originalShutdown=shutdown;shutdown=function(){windowShow('shutdown','Turn Off Computer',`<div class="setting"><h3>End Duty Support session?</h3><p>Progress is already saved. This only ends the game session.</p><div class="wizard-footer">${pageButton("logout(false)",'Turn Off')}${pageButton("closeWin('shutdown')",'Cancel')}</div></div>`,450)};
logout=function(withSound=true){pauseClip();stopAudio();stopCascade();[...windows.keys()].forEach(closeWin);saveIncident();paused=false;$('#toast').hidden=true;$('#startmenu').hidden=true;$('#login').hidden=false;$('#username').value=profile;if(withSound)playSound('logoff',true);else playSound('shutdown',true)};
function buildDesktop(){const items=[['computer','icon-16.ico','My Computer'],['files','folder.png','My Documents'],['mail','mail.png','Outlook Express'],['internet','ie.png','Internet Explorer'],['bookings','icon-16.ico','Reception PC-04'],['game','icon-35.ico','Recovery Log'],['journal','icon-35.ico','Case Notes'],['security','icon-48.ico','Security Center'],['settings','icon-36.ico','Control Panel']];$('.icons').innerHTML=items.map(([id,img,name])=>`<button class="shortcut" data-invest-open="${id}" title="Double-click or select and press Enter"><span class="ico"><img class="xp-icon" src="assets/${img}" alt=""></span>${name}</button>`).join('');document.querySelectorAll('[data-invest-open]').forEach(b=>{b.ondblclick=()=>openApp(b.dataset.investOpen);b.onclick=e=>{if(e.detail===0)openApp(b.dataset.investOpen)};b.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();openApp(b.dataset.investOpen)}}})}
$('#start').onclick=()=>{const m=$('#startmenu');m.hidden=!m.hidden;playSound('click');m.innerHTML=`<div class="starthead"><span class="avatar" style="margin:0;width:48px;height:48px"><img src="assets/user.png" alt=""></span>Duty Support · ${esc(profile)}</div><div class="startcols"><div>${[['internet','ie.png','Internet Explorer'],['mail','mail.png','Outlook Express'],['game','icon-35.ico','Recovery Log'],['journal','icon-35.ico','Case Notes'],['cctv','icon-16.ico','Saved CCTV clip']].map(([id,img,name])=>`<button onclick="openApp('${id}')"><img src="assets/${img}" alt="">${name}</button>`).join('')}</div><div>${[['files','folder.png','My Documents'],['computer','icon-16.ico','My Computer'],['settings','icon-36.ico','Control Panel'],['startup','icon-36.ico','Computer Management'],['help','icon-24.ico','Help and Handover']].map(([id,img,name])=>`<button onclick="openApp('${id}')"><img src="assets/${img}" alt="">${name}</button>`).join('')}<button onclick="openApp('run')">Run…</button></div></div><div class="startfoot"><button onclick="logout()">Log Off</button><button onclick="shutdown()">Turn Off Computer</button></div>`};
runCommand=function(command){closeWin('run');const commands={explorer:'files',notepad:'journal',iexplore:'internet',outlook:'mail',control:'settings','compmgmt.msc':'startup',recovery:'game',wmplayer:'cctv'};if(commands[command.trim().toLowerCase()])openApp(commands[command.trim().toLowerCase()]);else{playSound('error');info('Windows cannot find '+command+'. Available tools are listed in Start.')}};
$('#loginform').onsubmit=e=>{e.preventDefault();profile=$('#username').value.trim();if(!profile)return;const preAccess={...incident.access};incident=initialIncident();incident.access=preAccess;try{const old=JSON.parse(localStorage.getItem(incidentKey())||'null');if(old?.schemaVersion===2&&old.caseVersion===CASE.version)incident=old}catch{}incident.mode=incident.mode==='relaxed'?'relaxed':$('#relaxedLogin')?.checked?'relaxed':'standard';installed=true;practice=false;state={wrong:incident.unsafe,solved:!!incident.ending,chosen:[]};$('#login').hidden=true;paused=false;saveIncident();applyAccessibility();playSound('logon',true);if(incident.ending)openReport('R03');else if(incident.read.length||incident.ledger.length)openCase();else openBriefing();syncEffects()};
$('#audio').onclick=()=>{audioPrefs.enabled=!audioPrefs.enabled;if(!audioPrefs.enabled)stopAudio();saveAudio();if(audioPrefs.enabled)playSound('complete',true)};
document.addEventListener('visibilitychange',()=>{if(document.hidden){pauseClip();stopAudio();stopCascade();document.querySelectorAll('.cctv-scene').forEach(el=>el.classList.remove('playing'))}else syncEffects()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){pauseClip();stopAudio();document.querySelectorAll('.cctv-scene').forEach(el=>el.classList.remove('playing'))}});
const loginIntro=$('.login-brand p');loginIntro.textContent='To begin, choose your support session.';$('.login-form label[for="username"]').textContent='Duty Support';$('.login-form small').innerHTML='Authorised local support profile.<br>Reception’s session is preserved for investigation.';$('#loginform').insertAdjacentHTML('beforeend','<label class="login-option"><input id="relaxedLogin" type="checkbox"> Relaxed mode</label><button type="button" class="link login-settings" onclick="openPreloginSettings()">Sound and accessibility</button>');
function openPreloginSettings(){const el=windowShow('settings','Sound and Accessibility',`<div class="setting"><label class="check-row"><input type="checkbox" ${audioPrefs.enabled?'checked':''} onchange="audioPrefs.enabled=this.checked;saveAudio()"> Windows sounds on</label><label>System volume <input type="range" min="0" max="1" step=".05" value="${audioPrefs.system}" oninput="audioPrefs.system=Number(this.value);saveAudio()"></label><label class="check-row"><input type="checkbox" onchange="incident.access.reduced=this.checked;applyAccessibility()"> Reduced motion</label><p>More preferences are available in Control Panel after login.</p><div class="wizard-footer">${pageButton("closeWin('settings')",'Done')}</div></div>`,460);el.style.zIndex=1300}
buildDesktop();saveAudio();tick();document.title='DEADLINE XP — Duty Support / The Missing Morning';

function refreshToolStatus(type){if(windows.has('game'))openCase();if(type==='helper'&&windows.has('startup'))openStartup();if(type==='isolate'&&windows.has('network'))openNetwork();if(type==='quarantine'&&windows.has('timeline'))openTimeline();if(['stage','changes','test'].includes(type)&&windows.has('recovery'))openRecovery(type==='stage'?'copies':type==='changes'?'changes':'verify')}

function openThread(id){const groups=[['E02','E05','E24'],['E04','E17','E18'],['E06','E15','E16'],['E13','E14','E21'],['E07','E08','E09','E19','E27'],['E01','E12','E23','E25','E26','E28']];let ids=groups.find(g=>g.includes(id))||[id];ids=ids.filter(visibleArtifact);windowShow('thread','Outlook Express — Conversation',`<div class="network-body"><h3>Related shared-mailbox messages</h3><p>Messages are related by the office conversation, not evidence of a shared technical source.</p>${ids.map(key=>`<article class="thread-item"><b>${key} — ${esc(E[key].title)}</b><p>${esc(E[key].from)} · ${esc(incident.triggered[key]?.time||E[key].time)}</p><p>${esc(E[key].body).slice(0,220)}…</p><button class="link" onclick="viewEvidence('${key}')">Open original message</button></article>`).join('')}</div>`,720)}
